"""Author PRE_A1-U16 only; preserve previous sessions and lexical meanings."""
import json,copy,re,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[4]
KIT=ROOT/'plans/daily-practice-authoring'
OUT=Path(__file__).parent/'packages/PRE_A1'
level=json.loads((KIT/'levels/PRE_A1.plan.json').read_text())['level']
plan=level['units'][15]
W={}
for source in [OUT/f'PRE_A1-U{n:02}.v1.json' for n in range(15,1,-1)]+[KIT/'examples/PRE_A1-U01.v2.json']:
 for s in json.loads(source.read_text())['sessions']:
  for w in s['vocabulary']:W.setdefault(w['id'],copy.deepcopy(w))
for w in W.values():
 if 'example' not in w:w['example']=dict(fr=w['fr'],ru=w['ru'][0],transcription_ru=w['transcription_ru'])
OLD=set(W);FIRST={};S=[]
U='PRE_A1.U16.UNDERSTAND';A='PRE_A1.U16.APPLY'
OBJECTIVES={o['id']:o for u in level['units'] for o in u['objectives']}

def ru(t): return dict(text=t,text_lang='ru')

def fr(t,p): return dict(text=t,text_lang='fr',transcription_ru=p)

def ex(f,r,p): return dict(fr=f,ru=r,transcription_ru=p)

def sound(f,p): return dict(text=f,transcription_ru=p,lang='fr-FR',asset_id=None)

def wc(w): return fr(W[w]['fr'],W[w]['transcription_ru'])

def fb(g,b): return dict(correct=g,incorrect=b)

def opts(v): return [dict(id=f'c{i}',**(ru(t) if isinstance(t,str) else t)) for i,t in enumerate(v)]

def rev(i,p,cs,a,g,b): return dict(id=i,type='single_choice',instruction='Выберите один ответ.',prompt=p,choices=opts(cs),correct_choice_id=f'c{a}',feedback=fb(g,b))

def start(n,d,vs):
 p=plan['sessions'][n-1]; s={k:copy.deepcopy(p[k]) for k in ['id','title','order','kind','prerequisite_ids']}
 s.update(version=1,level='PRE_A1',unit_id=plan['id'],description=d,duration_minutes=6,objectives=copy.deepcopy(plan['objectives']),skills=[],vocabulary=[copy.deepcopy(W[w]) for w in vs],tasks=[],introductions=[]); S.append(s); return s

def base(s,sk,gs,vs,av,ins,p,g,b):
 for o in gs:
  if o not in [x['id'] for x in s['objectives']]: s['objectives'].append(copy.deepcopy(OBJECTIVES[o]))
 if sk not in s['skills']: s['skills'].append(sk)
 t=dict(id=f'Q{len(s["tasks"])+1:02}',instruction=ins,prompt=p,feedback=fb(g,b),objective_ids=gs,skill=sk,vocabulary_ids=vs,assessed_vocabulary_ids=av); s['tasks'].append(t); return t

def choose(s,sk,gs,vs,av,ins,p,cs,a,g,b):
 t=base(s,sk,gs,vs,av,ins,p,g,b); t.update(type='single_choice',choices=opts(cs),correct_choice_id=f'c{a}'); return t

def listen(s,gs,vs,av,q,f,p,cs,a,g,b):
 return choose(s,'listening',gs,vs,av,'Прослушайте и выберите ответ.',dict(**ru(q),audio=sound(f,p)),cs,a,g,b)

def intro(s,n,t,vs,ns=(),au=None):
 i=dict(id=f'I{len(s["introductions"])+1:02}',before_task_id=f'Q{n:02}',text=t,vocabulary_ids=vs)
 if ns:i['pronunciation_notes']=[dict(fr=f,transcription_ru=p) for f,p in ns]
 if au:i['audio']=sound(*au)
 s['introductions'].append(i)

def pairs(s,gs,rows,g,b):
 vs=[w for w,r in rows]; t=base(s,'vocabulary',gs,vs,vs,'Соедините каждую карточку с её значением.',ru('Используйте все карточки по одному разу.'),g,b)
 t.update(type='matching_pairs',left_items=[dict(id=f'l{i}',**wc(w)) for i,(w,r) in enumerate(rows)],right_items=[dict(id=f'r{i}',**ru(r)) for i,(w,r) in reversed(list(enumerate(rows)))],correct_pairs=[dict(left_id=f'l{i}',right_id=f'r{i}',assessed_vocabulary_ids=[w]) for i,(w,r) in enumerate(rows)])

def order(s,gs,vs,av,ins,ts,f,p,g,b):
 t=base(s,'sentence_building',gs,vs,av,ins,ru('Нажимайте на карточки в нужном порядке.'),g,b); tokens=[dict(id=f't{i}',**fr(f,p)) for i,(f,p) in enumerate(ts)]
 t.update(type='word_order',tokens=list(reversed(tokens)),accepted_orders=[[x['id'] for x in tokens]],completed_phrases=[dict(fr=f,transcription_ru=p)])

def fill(s,gs,vs,av,ins,bef,bp,aft,ap,cs,a,f,p,g,b):
 t=base(s,'vocabulary',gs,vs,av,ins,ru('Выберите одну карточку для пропуска.'),g,b)
 t.update(type='fill_blank',input_mode='choice',text_before=bef,text_before_transcription_ru=bp,text_after=aft,text_after_transcription_ru=ap,choices=opts(cs),correct_choice_id=f'c{a}',completed_phrases=[dict(fr=f,transcription_ru=p)])

 return t

def page(s,blocks):
 s['public_page']=dict(slug=s['id'].lower().replace('_','-'),summary=s['description'],seo_title=s['title']+' — французский с нуля',seo_description=s['description'],explanation_blocks=[dict(heading=h,paragraphs=ps,examples=es) for h,ps,es in blocks])

def grammar(t):
 t['skill']='grammar'
 return t

def phrase_pairs(s,gs,rows,g,b):
 vs=list(dict.fromkeys(w for f,p,r,ws,av in rows for w in ws)); avs=list(dict.fromkeys(w for f,p,r,ws,av in rows for w in av))
 t=base(s,'vocabulary',gs,vs,avs,'Соедините реплику или выражение с его смыслом.',ru('Используйте каждую карточку один раз.'),g,b)
 t.update(type='matching_pairs',left_items=[dict(id=f'l{i}',**fr(f,p)) for i,(f,p,r,ws,av) in enumerate(rows)],right_items=[dict(id=f'r{i}',**ru(r)) for i,(f,p,r,ws,av) in reversed(list(enumerate(rows)))],correct_pairs=[dict(left_id=f'l{i}',right_id=f'r{i}',assessed_vocabulary_ids=av) for i,(f,p,r,ws,av) in enumerate(rows)])
 return t

def addword(i,key,f,r,p,e,n,reviews):
 W[i]=dict(id=i,lexeme_key=key,fr=f,ru=[r],transcription_ru=p,example=e,review_items=reviews);FIRST[i]=n
addword('maison','fr:maison:house-home','une maison','дом (здание; место дома)','юн мэзо́(н)',ex('Il y a une maison.','Есть дом.','иль я юн мэзо́(н)'),1,[rev('maison-meaning',fr('Une maison','юн мэзо́(н)'),['Школа','Дом','Магазин'],1,'Назван дом.','Правильное значение — дом; школа и магазин обозначают другие места.'),rev('maison-use',ru('В описании есть дом. Какой полный изученный образец выбрать?'),[fr('Il y a une école.','иль я юн эко́ль'),fr('Il y a du soleil.','иль я дю солэ́й'),fr('Il y a une maison.','иль я юн мэзо́(н)')],2,'Фраза сообщает о наличии дома.','Нужен дом; школа и солнечная погода не сохраняют условие.')])
addword('ecole','fr:ecole:school','une école','школа','юн эко́ль',ex('Il y a une école.','Есть школа.','иль я юн эко́ль'),1,[rev('ecole-meaning',fr('Une école','юн эко́ль'),['Школа','Дом','Парк'],0,'Названа школа.','Правильное значение — школа; дом и парк обозначают другие места.'),rev('ecole-use',ru('Нужно сообщить «Есть школа». Какую фразу выбрать?'),[fr('Il y a une maison.','иль я юн мэзо́(н)'),fr('Il y a une école.','иль я юн эко́ль'),fr('Il y a du soleil.','иль я дю солэ́й')],1,'Фраза сообщает о наличии школы.','Нужна школа; дом и солнечная погода не соответствуют условию.')])
addword('cafe-lieu','fr:cafe:venue','un café','кафе (заведение, место встречи)','э(н) кафэ́',ex('Rendez-vous au café.','Встреча в кафе.','ра(н)дэ-ву о кафэ́'),2,[rev('cafe-lieu-meaning',ru('В разделе о местах города «un café» называет заведение, где встречаются за напитком. Какое значение здесь нужно?'),['Порция кофе','Кафе как заведение','Магазин'],1,'Здесь имеется в виду кафе как место.','В данном контексте нужно заведение, а не порция напитка и не магазин.'),rev('cafe-lieu-use',ru('Нужно сообщить, что в описываемом городе есть кафе как заведение. Какой образец выбрать?'),[fr('Il y a un café.','иль я э(н) кафэ́'),fr('Il y a un magasin.','иль я э(н) магазэ́(н)'),fr('Il y a une école.','иль я юн эко́ль')],0,'В контексте городских мест фраза сообщает о кафе.','Нужно кафе как заведение; магазин и школа не соответствуют условию.')])
addword('magasin','fr:magasin:shop','un magasin','магазин','э(н) магазэ́(н)',ex('Rendez-vous au magasin.','Встреча в магазине.','ра(н)дэ-ву о магазэ́(н)'),2,[rev('magasin-meaning',fr('Un magasin','э(н) магазэ́(н)'),['Дом','Кафе как заведение','Магазин'],2,'Назван магазин.','Правильное значение — магазин; дом и кафе обозначают другие места.'),rev('magasin-use',ru('В городском описании нужно сообщить «Есть магазин». Какую фразу выбрать?'),[fr('Il y a un café.','иль я э(н) кафэ́'),fr('Il y a un magasin.','иль я э(н) магазэ́(н)'),fr('Il y a une maison.','иль я юн мэзо́(н)')],1,'Фраза сообщает о наличии магазина.','Нужен магазин; кафе и дом меняют условие.')])
addword('parc','fr:parc:park','un parc','парк','э(н) па́рк',ex('Rendez-vous au parc.','Встреча в парке.','ра(н)дэ-ву о па́рк'),3,[rev('parc-meaning',fr('Un parc','э(н) па́рк'),['Парк','Улица','Магазин'],0,'Назван парк.','Правильное значение — парк; улица и магазин обозначают другие места.'),rev('parc-use',ru('Нужно записать «Встреча в парке». Какую изученную запись выбрать?'),[fr('Rendez-vous au café.','ра(н)дэ-ву о кафэ́'),fr('Rendez-vous au magasin.','ра(н)дэ-ву о магазэ́(н)'),fr('Rendez-vous au parc.','ра(н)дэ-ву о па́рк')],2,'Встреча назначена в парке.','Нужен парк; кафе и магазин меняют место встречи.')])
addword('rue','fr:rue:street','une rue','улица','юн рю́',ex('Rue du Parc.','Улица Парка (название в учебной схеме).','рю дю па́рк'),3,[rev('rue-meaning',fr('Une rue','юн рю́'),['Школа','Улица','Парк'],1,'Названа улица.','Правильное значение — улица; школа и парк обозначают другие места.'),rev('rue-use',ru('В учебной схеме нужно выбрать подпись улицы Парка. Какую подпись выбрать?'),[fr('Un parc.','э(н) па́рк'),fr('Une école.','юн эко́ль'),fr('Rue du Parc.','рю дю па́рк')],2,'Выбрано полное название улицы в учебной схеме.','Нужно название улицы; отдельные названия парка и школы не отвечают условию.')])
addword('cest-ou','fr:cest-ou:place-location-question','c’est où ?','где это? (вопрос о месте)','сэ у́',ex('Le café, c’est où ?','Кафе где находится?','лё кафэ, сэ у́'),4,[rev('cest-ou-meaning',fr('C’est où ?','сэ у́'),['Где это?','Когда встреча?','Какая погода?'],0,'Это короткий вопрос о месте.','Нужен смысл «Где это?»; время встречи и погода спрашиваются иначе.'),rev('cest-ou-use',ru('Вы хотите узнать, где находится знакомое кафе. Какой вопрос выбрать?'),[fr('Rendez-vous quand ?','ра(н)дэ-ву ка́(н)'),fr('Le café, c’est où ?','лё кафэ, сэ у́'),fr('Quel temps fait-il ?','кэль та(н) фэ ти́ль')],1,'Вопрос спрашивает о расположении кафе.','Нужно спросить где кафе; вопрос о времени встречи и вопрос о погоде имеют другую цель.')])

def cards(ids):return [wc(x) for x in ids]
s=start(1,'Узнавайте дом и школу в коротком описании. Перенесите знакомое погодное начало в явно показанные образцы наличия городских мест.',['maison','ecole','soleil','il-pleut'])
choose(s,'reading',['PRE_A1.U15.UNDERSTAND'],['il-pleut','soleil'],['il-pleut'],'Что сообщает знакомая погодная фраза?',fr('Il pleut.','иль плё́.'),['Солнечно','Идёт дождь','Погода не названа'],1,'Фраза сообщает дождь.','Нужен смысл «Идёт дождь»; солнечная погода выражается другим образцом.')
intro(s,2,'Une maison — «дом», une école — «школа». Оба названия в этих образцах женского рода; учим их с артиклем. Теперь явно расширяем знакомое начало: Il y a une maison. — «Есть дом», Il y a une école. — «Есть школа». Это сообщения о наличии места в описании. Сохраняйте показанные сочетания целиком; знакомая фраза Il y a du soleil. по-прежнему сообщает солнечную погоду.',['maison','ecole'],[('Une maison','юн мэзо́(н)'),('une école','юн эко́ль'),('Il y a une maison.','иль я юн мэзо́(н)'),('Il y a une école.','иль я юн эко́ль'),('Il y a du soleil.','иль я дю солэ́й')],('Il y a une maison. Il y a une école.','иль я юн мэзо́(н). иль я юн эко́ль.'))
phrase_pairs(s,[U,'PRE_A1.U15.UNDERSTAND'],[('Il y a une maison.','иль я юн мэзо́(н).','Есть дом.',['maison'],['maison']),('Il y a une école.','иль я юн эко́ль.','Есть школа.',['ecole'],['ecole']),('Il y a du soleil.','иль я дю солэ́й.','Солнечно.',['soleil'],['soleil'])],'Вы различили два места и знакомое сообщение о погоде.','Смотрите на всё сочетание после начала: дом, школа и солнечная погода имеют разные значения.')
listen(s,[U],['ecole','maison','soleil'],['ecole'],'Какое место названо в сообщении?','Il y a une école.','иль я юн эко́ль.',['Дом','Солнечная погода','Школа'],2,'Сообщается, что есть школа.','Названа школа; дом и солнечная погода не соответствуют фразе.')
choose(s,'vocabulary',[U],['maison','ecole','soleil'],['maison'],'Нужно сообщить «Есть дом». Какую фразу выбрать?',ru('Выберите место из условия.'),[fr('Il y a une maison.','иль я юн мэзо́(н).'),fr('Il y a une école.','иль я юн эко́ль.'),fr('Il y a du soleil.','иль я дю солэ́й.')],0,'Выбран образец о наличии дома.','Нужен дом; школа и солнечная погода меняют смысл условия.')
intro(s,5,'В подписи уже названных мест встречаются готовые формы La maison — «дом» и L’école — «школа». Это те же названия, с другой показанной формой артикля. Слово с апострофом сохраняем целиком. Общую таблицу артиклей сейчас не учим.',['maison','ecole'],[('La maison','ла мэзо́(н)'),('L’école','лэко́ль')],('La maison. L’école.','ла мэзо́(н). лэко́ль.'))
choose(s,'reading',[U],['maison','ecole'],['maison','ecole'],'Какие два места перечислены в подписях?',fr('La maison. L’école.','ла мэзо́(н). лэко́ль.'),['Дом и кафе','Дом и школа','Школа и улица'],1,'Перечислены дом и школа.','Прочитайте оба названия: дом и школа. Кафе и улица в этих подписях не названы.')
fill(s,[U],['ecole','maison','soleil'],['ecole'],'Дополните сообщение «Есть школа».','Il y a ','иль я́','','',[fr('une maison','юн мэзо́(н)'),fr('du soleil','дю солэ́й'),fr('une école','юн эко́ль')],2,'Il y a une école','иль я юн эко́ль','Выбрано название школы с показанным артиклем.','Нужна школа; дом и сочетание о солнце не соответствуют условию.')
order(s,[U],['maison'],[],'Соберите «Есть дом». Начните с целого показанного начала.',[('Il y a','иль я́'),('une','юн'),('maison.','мэзо́(н)')],'Il y a une maison.','иль я юн мэзо́(н).','Получилась полная фраза о наличии дома.','Поставьте начало первым, затем артикль из образца и название дома.')
page(s,[('Дом и школа',['Два названия учатся с артиклем. В коротком описании готовое начало сообщает, что такое место есть.'],[W['maison']['example'],W['ecole']['example']]),('Знакомые места в подписях',['В подписи уже названного места используются показанные формы с другим артиклем. Форма с апострофом остаётся целым словом.'],[ex('La maison.','Дом.','ла мэзо́(н)'),ex('L’école.','Школа.','лэко́ль')]),('Расширение известного образца',['Погодный образец не заменяет объяснение новой ситуации. Здесь отдельно показаны полные фразы о наличии дома и школы.'],[ex('Il y a une maison.','Есть дом.','иль я юн мэзо́(н)'),W['soleil']['example']])])
s=start(2,'Различайте кафе как заведение и магазин. Выбирайте готовую запись о встрече в одном из этих мест.',['cafe-lieu','magasin','maison','ecole','cafe','je-voudrais','rendez-vous'])
choose(s,'reading',[U],['maison','ecole'],['ecole'],'Какое место названо в знакомой фразе?',fr('Il y a une école.','иль я юн эко́ль.'),['Дом','Школа','Кафе'],1,'Сообщается о школе.','Нужна школа; дом и кафе обозначают другие места.')
intro(s,2,'В теме городских мест un café означает «кафе как заведение», un magasin — «магазин». Написание названия кафе совпадает со знакомым названием порции кофе, но здесь другое значение. Образцы о местах: Il y a un café. — «Есть кафе», Il y a un magasin. — «Есть магазин». Контекст городских мест задаёт нужное значение.',['cafe-lieu','magasin'],[('un café','э(н) кафэ́'),('un magasin','э(н) магазэ́(н)'),('Il y a un café.','иль я э(н) кафэ́'),('Il y a un magasin.','иль я э(н) магазэ́(н)')],('Il y a un café. Il y a un magasin.','иль я э(н) кафэ́. иль я э(н) магазэ́(н).'))
